SELECT FROM ink_template t LEFT JOIN ink_signature s ON t.signature_id = s.id
AND (t.name LIKE CONCAT('%', #{keyword}, '%') OR t.content LIKE CONCAT('%', #{keyword}, '%'))
AND t.status = #{status}
